/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert("저장에 실패하였습니다.");
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07103.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        scwin.indexingElasitcSearch();
        await $c.win.alert("저장하였습니다.");
        scwin.parentRefresh();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07103.trs_Save_OnSuccess" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (js_dep_cd.substring(0, 2) !== '25' && // 유가증권시장본부 - 상장부
        js_dep_cd.substring(0, 2) !== '33' && // 코스닥시장본부 -  상장부
        js_dep_cd.substring(0, 2) !== '3E' && // 기술기업상장부
        js_dep_cd !== '2615') // 기업심사팀 by nhkw

    {
        await $c.win.alert("해당 부서만 접수가 가능합니다.");
        return;
    }
    if (await scwin.checkInput() === false) {
        return;
    }
    const res = window.confirm("예비심사청구 절차를 저장합니다.\n\n계속하시겠습니까?");
    if (res) {
        trs_Save.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/Prelisting.do",
            ref : "dts_Grid",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        // 청구서 접수일자를 업데이트 한다.
        /*
        trs_Save.Action   = "/lstinvstg/PrelmInvstg.do?SCREN_ID="+vScrenID+"&SCREN_PROCES_TP_CD="+SCREN_PROCS_TP_CD_02+"&method=modifyAcptDd";
        trs_Save.KeyName  = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_Grid)";
        trs_Save.Parameters  = "TRS_IDX=U" +
        								", ACPT_DD=" + edt_STEP01_DATE.GetSelClipText(0,8) +
        								", BZ_PROCS_NO="+ strBzProcsNo;

        trs_Save.Post();
         */

    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name hideDebugCtrls
 * @description hide Debug Ctrls 처리
 * @returns {void}
 * @hidden N
 */
scwin.hideDebugCtrls = function() {
    panel_debug.hide();
};

/**
 * @method
 * @name parentRefresh
 * @description parent Refresh 처리
 * @returns {void}
 * @hidden N
 */
scwin.parentRefresh = function() {
    const fr_fn_list_sync = $c.frame.path("../").fn_list_sync;
    fr_fn_list_sync();
};

/**
 * @method
 * @name checkInput
 * @description check Input 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkInput = async function() {
    const sSTEP01 = dts_Grid.getCellData(1, "STEP01");
    dts_Grid.setCellData(1, "STEP02", "0");
    dts_Grid.setCellData(1, "STEP03", "0");
    dts_Grid.setCellData(1, "STEP04", "0");
    dts_Grid.setCellData(1, "STEP05", "0");
    const sSTEP06 = dts_Grid.getCellData(1, "STEP06");
    dts_Grid.setCellData(1, "STEP07", "0");
    dts_Grid.setCellData(1, "STEP08", "0");
    dts_Grid.setCellData(1, "STEP09", "0");
    const sSTEP10 = dts_Grid.getCellData(1, "STEP10");
    const sSTEP11 = dts_Grid.getCellData(1, "STEP11");
    const sSTEP12 = dts_Grid.getCellData(1, "STEP12");
    const sSTEP13 = dts_Grid.getCellData(1, "STEP13");
    const sSTEP14 = dts_Grid.getCellData(1, "STEP14");
    const sSTEP15 = dts_Grid.getCellData(1, "STEP15");
    dts_Grid.setCellData(1, "STEP16", "0");
    const sSTEP17 = dts_Grid.getCellData(1, "STEP17"); // 상장위원회결과 통보 20180406
    const sSTEP18 = dts_Grid.getCellData(1, "STEP18"); // 시장위원회결과 통보 20180406
    const cSTEP17 = dts_Grid.getCellData(1, "STEP17_DATE"); // 상장위원회결과 통보 20180406
    const cSTEP18 = dts_Grid.getCellData(1, "STEP18_DATE"); // 시장위원회결과 통보 20180406
    if (sSTEP01 === "0" && sSTEP06 === "0" &&
        sSTEP10 === "0" && sSTEP11 === "0" &&
        sSTEP12 === "0" && sSTEP13 === "0" &&
        sSTEP14 === "0" && sSTEP15 === "0" &&
        sSTEP17 === "0" && sSTEP18 === "0") {
        // 20180406
        await $c.win.alert("저장할 상태가 없습니다.");
        return false;
    }

    // 상장위원회 결과
    if (sSTEP17 === "1") {
        if (dts_Grid.getCellData(1, "STEP17_APPROV_YN") === '' || cSTEP17 === '') {
            await $c.win.alert("'상장위원회결과 통보'의 '결과'와 '일자'는 필수값 입니다.");
            return false;
        }
    }

    // 시장위원회 결과
    if (sSTEP18 === "1") {
        if (dts_Grid.getCellData(1, "STEP18_APPROV_YN") === '' || cSTEP18 === '') {
            await $c.win.alert("'시장위원회결과 통보'의 '결과'와 '일자'는 필수값 입니다.");
            return false;
        }
    }

    // 예비심사결과 통보
    if (sSTEP06 === "1") {
        if (dts_Grid.getCellData(1, "APPROV_YN") === '' || dts_Grid.getCellData(1, "STEP06_DATE") === '') {
            await $c.win.alert("'예비심사결과 통보'의 '결과'와 '일자'는 필수값 입니다.");
            return false;
        }
    }

    // 예비심사 철회
    if (sSTEP12 === "1") {
        if (dts_Grid.getCellData(1, "STEP12_DATE") === '') {
            await $c.win.alert("'예비심사 철회'의 '일자'는 필수값 입니다.");
            return false;
        }
    }
};

/**
 * @method
 * @name indexingElasitcSearch
 * @description indexing Elasitc Search 처리
 * @returns {void}
 * @hidden N
 */
scwin.indexingElasitcSearch = function() {
    list_invstg_attach(scwin.vBzProcsNo, "00", "10");
};
